 for(const[name,kind]of [['AddRun','plain'],['AddPositionedRun','positioned'],['AddHorizontalRun','horizontal'],['AddRotationScaleRun','rotation']]){SKTextBlobBuilder.prototype[name]=function(ids,font,...rest){this.ThrowIfDisposed();ids=glyphs(ids,font);let blob,x=0,y=0;if(kind==='plain'){const p=origin(rest[0]??0,rest[1]??0);x=p.X;y=p.Y;blob=SKTextBlob.CreatePositioned(ids,font,font.GetGlyphPositions(ids));}else if(kind==='positioned')blob=SKTextBlob.CreatePositioned(ids,font,rest[0]);else if(kind==='horizontal')blob=SKTextBlob.CreateHorizontal(ids,font,rest[0],rest[1]??0);else blob=SKTextBlob.CreateRotationScale(ids,font,rest[0]);this._runs.push({blob,x,y});return this;};}
